package app.truemotion.vector;
import android.graphics.*;
import java.io.*;
import java.util.*;
final class PsdRaster {
 static VectorDocument document(PsdFile psd,double fps,int frames)throws Exception{VectorDocument doc=new VectorDocument(psd.width,psd.height,fps,frames);doc.tracks.clear();ArrayList<PsdFile.Layer> layers=new ArrayList<PsdFile.Layer>(psd.layers);/* PSD records and VectorDocument tracks both run from background to foreground. */if(layers.isEmpty()&&psd.composite!=null){PsdFile.Layer layer=new PsdFile.Layer();layer.name=L10n.t("PSD изображение");layer.width=psd.width;layer.height=psd.height;layer.pixels=psd.composite;layers.add(layer);}for(PsdFile.Layer layer:layers){if(layer.pixels==null||layer.section!=0)continue;WorkBudget.memory((long)layer.width*layer.height*12);Bitmap bitmap=Bitmap.createBitmap(layer.pixels,layer.width,layer.height,Bitmap.Config.ARGB_8888);ByteArrayOutputStream out=new ByteArrayOutputStream();try{bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}finally{bitmap.recycle();}VectorImage image=VectorRaster.image(out.toByteArray());doc.images.put(image.id,image);VectorDocument.Track track=new VectorDocument.Track(layer.name);track.visible=(layer.flags&2)==0;VectorDocument.Shape shape=new VectorDocument.Shape();shape.image=image.id;shape.name=layer.name;shape.imageRect=new int[]{0,0,layer.width,layer.height};shape.imageFrame=new int[]{layer.width,layer.height,0,0};shape.x=layer.left+layer.width/2d;shape.y=layer.top+layer.height/2d;shape.opacity=layer.opacity/255d;track.keys.get(0).shapes.add(shape);doc.tracks.add(track);layer.pixels=null;}if(doc.tracks.isEmpty())throw new IOException(L10n.t("PSD не содержит поддерживаемых растровых слоёв"));doc.validate();return doc;}
}
